def _plain_to_html(text):
    out = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        if line.startswith("## "):
            out.append("<h2>%s</h2>" % html.escape(line[3:]))
        else:
            out.append("<p>%s</p>" % html.escape(line))
    return "".join(out)

